const __pageData = JSON.parse('{"title":"Kash Patel","description":"","frontmatter":{"title":"Kash Patel","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["trump-allies","america-first",2022,"media"],"sources":["raw/all-assets-deployed.md","raw/badlands-brief-1ef.md","raw/badlands-brief-40d.md","raw/badlands-brief-50d.md","raw/badlands-brief-509.md","raw/badlands-brief-625.md","raw/badlands-brief-6b4.md","raw/badlands-brief-724.md","raw/badlands-brief-835.md","raw/badlands-brief-8c2.md","raw/badlands-brief-a84.md","raw/badlands-brief-a20.md","raw/badlands-brief-c07.md","raw/badlands-brief-d3b.md","raw/badlands-news-brief-02a.md","raw/badlands-news-brief-099.md","raw/badlands-news-brief-144.md","raw/badlands-news-brief-1e6.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-243.md","raw/badlands-news-brief-316.md","raw/badlands-news-brief-356.md","raw/badlands-news-brief-351.md","raw/badlands-news-brief-397.md","raw/badlands-news-brief-3d2.md","raw/badlands-news-brief-410.md","raw/badlands-news-brief-42b.md","raw/badlands-news-brief-433.md","raw/badlands-news-brief-457.md","raw/badlands-news-brief-448.md","raw/badlands-news-brief-576.md","raw/badlands-news-brief-5a3.md","raw/badlands-news-brief-656.md","raw/badlands-news-brief-732.md","raw/badlands-news-brief-745.md","raw/badlands-news-brief-757.md","raw/badlands-news-brief-779.md","raw/badlands-news-brief-7b8.md","raw/badlands-news-brief-8cd.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/kash-patel.md","filePath":"entities/kash-patel.md","lastUpdated":null}');
